"""Carga única en memoria de los Parquet generados por el ETL.

Este módulo se ejecuta una sola vez al arrancar el kernel Pyodide, dejando
los DataFrames disponibles para todos los módulos de la app.
"""

from __future__ import annotations

import json
from pathlib import Path

import pandas as pd
import pyarrow.parquet as pq

DATA_DIR = Path(__file__).parent / "data"


def _read(name: str) -> pd.DataFrame:
    """Lee un Parquet con manejo robusto de archivos ausentes."""
    path = DATA_DIR / f"{name}.parquet"
    if not path.exists():
        return pd.DataFrame()
    try:
        return pq.read_table(path).to_pandas()
    except Exception:
        return pd.DataFrame()


# ─── Datasets ─────────────────────────────────────────────────────────────────

personas: pd.DataFrame = _read("personas")
actividades: pd.DataFrame = _read("actividades")
participaciones: pd.DataFrame = _read("participaciones")
alias: pd.DataFrame = _read("alias")
centros: pd.DataFrame = _read("centros")
revistas: pd.DataFrame = _read("revistas")
congresos: pd.DataFrame = _read("congresos")
externos: pd.DataFrame = _read("coautores_externos")
duplicados: pd.DataFrame = _read("duplicados")

# Manifest
_manifest_path = DATA_DIR / "manifest.json"
manifest: dict = (
    json.loads(_manifest_path.read_text(encoding="utf-8")) if _manifest_path.exists() else {}
)

# ─── Índices auxiliares ───────────────────────────────────────────────────────

# id_persona → dict de la fila (acceso por nombre con [..] e .get(..))
PERSONAS_BY_ID: dict[int, dict] = (
    {int(r["id_persona"]): r.to_dict() for _, r in personas.iterrows()}
    if not personas.empty
    else {}
)

def _build_persona_choices() -> dict[str, str]:
    """Genera el dict {id: label} para selectize.

    Label limpio: "Apellidos, Nombre" (ej. "Cuesta Mariscal, Jose Antonio").
    Sin sufijos de alias — el dropdown debe ser sobrio.
    """
    if personas.empty:
        return {}
    choices: dict[str, str] = {}
    for _, r in personas.sort_values("nombre_display").iterrows():
        pid = int(r["id_persona"])
        display = r["nombre_display"] or r.get("nombre_canonico_largo") or f"Persona {pid}"
        choices[str(pid)] = display
    return choices


PERSONA_CHOICES: dict[str, str] = _build_persona_choices()


def join_actividades_persona(id_persona: int) -> pd.DataFrame:
    """Devuelve todas las actividades en las que participa una persona."""
    if participaciones.empty or actividades.empty:
        return pd.DataFrame()
    sub = participaciones[participaciones["id_persona"] == id_persona]
    if sub.empty:
        return pd.DataFrame()
    ids = sub["id_actividad"].dropna().astype(int).tolist()
    df = actividades[actividades["id_actividad"].astype("Int64").isin(ids)].copy()
    return df.sort_values("fecha", ascending=False, na_position="last").reset_index(drop=True)


def coauthors_of(id_persona: int) -> pd.DataFrame:
    """Devuelve los coautores ICMAN más frecuentes de una persona, con peso."""
    if participaciones.empty:
        return pd.DataFrame(columns=["id_persona", "nombre", "n_coauthors"])
    target_acts = set(
        participaciones.loc[participaciones["id_persona"] == id_persona, "id_actividad"]
        .dropna()
        .astype(int)
        .tolist()
    )
    if not target_acts:
        return pd.DataFrame(columns=["id_persona", "nombre", "n_coauthors"])
    # Otros participantes en esas actividades
    coauths = participaciones[
        participaciones["id_actividad"].astype("Int64").isin(target_acts)
        & (participaciones["id_persona"] != id_persona)
    ]
    if coauths.empty:
        return pd.DataFrame(columns=["id_persona", "nombre", "n_coauthors"])
    counts = coauths.groupby("id_persona").size().reset_index(name="n_coauthors")
    counts = counts.merge(
        personas[["id_persona", "nombre_display"]], on="id_persona", how="left"
    ).rename(columns={"nombre_display": "nombre"})
    return counts.sort_values("n_coauthors", ascending=False).reset_index(drop=True)


def alias_for(id_persona: int) -> pd.DataFrame:
    """Devuelve los alias (firmas) de una persona ordenados por frecuencia."""
    if alias.empty:
        return pd.DataFrame(columns=["alias", "frecuencia", "origen"])
    return (
        alias[alias["id_persona"] == id_persona][["alias", "frecuencia", "origen"]]
        .sort_values("frecuencia", ascending=False)
        .reset_index(drop=True)
    )


# ─── Constantes derivadas ────────────────────────────────────────────────────

TIPOS_DISPONIBLES: list[str] = (
    sorted(actividades["tipo"].dropna().unique().tolist()) if not actividades.empty else []
)
IDIOMAS_DISPONIBLES: list[str] = (
    sorted(actividades["idioma"].dropna().unique().tolist()) if not actividades.empty else []
)
ANIO_MIN, ANIO_MAX = (
    (int(actividades["anio"].min()), int(actividades["anio"].max()))
    if not actividades.empty and actividades["anio"].notna().any()
    else (2025, 2025)
)


def n_actividades_por_tipo() -> dict[str, int]:
    if actividades.empty:
        return {}
    return actividades["tipo"].value_counts().to_dict()

/* ICMAN-CSIC · Producción Científica
   Paletas seleccionables vía  data-palette  en <html>.
   Por defecto: navbar BLANCO con letras OSCURAS, fondo de página neutro. */

:root {
  /* Constantes de marca (no cambian con la paleta) */
  --icman-deep:    #0a3d4a;
  --icman-medium:  #1d6e7e;
  --icman-coast:   #5fb7c2;
  --icman-foam:    #e6f4f6;
  --icman-sand:    #f6efe2;
  --icman-coral:   #d97559;
  --csic-red:      #c4372f;

  /* ============== PALETA POR DEFECTO · CLARO ============== */
  --bg-app:           #ffffff;
  --bg-surface:       #ffffff;
  --bg-subtle:        #f3f7f8;
  --bg-card-header:   #eef5f6;
  --text-primary:     #0e2a32;
  --text-secondary:   #4a5d63;
  --text-heading:     #0a3d4a;
  --border-subtle:    #d7e4e7;
  --shadow-card:      0 1px 3px rgba(0,0,0,0.05);
  --shadow-card-hov:  0 4px 12px rgba(10,61,74,0.10);
  --link:             #1d6e7e;
  --link-hover:       #0a3d4a;
  --accent:           #5fb7c2;
  --accent-strong:    #1d6e7e;

  /* Navbar: fondo claro, texto OSCURO */
  --navbar-bg:           #ffffff;
  --navbar-bg-end:       #ffffff;
  --navbar-text:         #0a3d4a;
  --navbar-text-mute:    #1d6e7e;
  --navbar-active-bg:    rgba(29, 110, 126, 0.12);
  --navbar-active-text:  #0a3d4a;
  --navbar-hover-bg:     rgba(29, 110, 126, 0.08);
  --navbar-border:       #5fb7c2;
}

/* ============== PALETA · CREMA / ARENA ============== */
html[data-palette="crema"] {
  --bg-app:           #faf4e6;
  --bg-surface:       #fffaf0;
  --bg-subtle:        #f3ead4;
  --bg-card-header:   #f6efe2;
  --text-primary:     #3a2810;
  --text-secondary:   #6b513b;
  --text-heading:     #5a3a1a;
  --border-subtle:    #e2d3b3;
  --link:             #b85a3a;
  --link-hover:       #8a3f24;
  --accent:           #d97559;
  --accent-strong:    #b85a3a;

  --navbar-bg:           #fffaf0;
  --navbar-bg-end:       #f6efe2;
  --navbar-text:         #5a3a1a;
  --navbar-text-mute:    #8a5a30;
  --navbar-active-bg:    rgba(217, 117, 89, 0.18);
  --navbar-active-text:  #3a2810;
  --navbar-hover-bg:     rgba(217, 117, 89, 0.10);
  --navbar-border:       #d97559;
}

/* ============== PALETA · MARINA SUAVE ============== */
html[data-palette="marina"] {
  --bg-app:           #e6f4f6;
  --bg-surface:       #ffffff;
  --bg-subtle:        #d4e9ec;
  --bg-card-header:   #cfe5e8;
  --text-primary:     #06222a;
  --text-secondary:   #3d575c;
  --text-heading:     #0a3d4a;
  --border-subtle:    #b4d2d6;
  --link:             #1d6e7e;
  --link-hover:       #0a3d4a;
  --accent:           #1d6e7e;
  --accent-strong:    #0a3d4a;

  --navbar-bg:           #ffffff;
  --navbar-bg-end:       #ffffff;
  --navbar-text:         #0a3d4a;
  --navbar-text-mute:    #1d6e7e;
  --navbar-active-bg:    rgba(10, 61, 74, 0.10);
  --navbar-active-text:  #0a3d4a;
  --navbar-hover-bg:     rgba(10, 61, 74, 0.06);
  --navbar-border:       #1d6e7e;
}

/* ============== PALETA · OSCURO ============== */
html[data-palette="oscuro"] {
  --bg-app:           #06181d;
  --bg-surface:       #0e2a32;
  --bg-subtle:        #102f38;
  --bg-card-header:   #0a3d4a;
  --text-primary:     #e6f4f6;
  --text-secondary:   #a7c0c5;
  --text-heading:     #ffffff;
  --border-subtle:    #1d4554;
  --shadow-card:      0 1px 3px rgba(0,0,0,0.4);
  --shadow-card-hov:  0 4px 18px rgba(0,0,0,0.55);
  --link:             #92cdd4;
  --link-hover:       #bee0e4;
  --accent:           #5fb7c2;
  --accent-strong:    #92cdd4;

  --navbar-bg:           #0a3d4a;
  --navbar-bg-end:       #1d6e7e;
  --navbar-text:         #ffffff;
  --navbar-text-mute:    rgba(255,255,255,0.85);
  --navbar-active-bg:    rgba(255,255,255,0.20);
  --navbar-active-text:  #ffffff;
  --navbar-hover-bg:     rgba(255,255,255,0.10);
  --navbar-border:       #5fb7c2;
}

/* ============== PALETA · ALTO CONTRASTE ============== */
html[data-palette="alto-contraste"] {
  --bg-app:           #ffffff;
  --bg-surface:       #ffffff;
  --bg-subtle:        #f5f5f5;
  --bg-card-header:   #000000;
  --text-primary:     #000000;
  --text-secondary:   #1a1a1a;
  --text-heading:     #000000;
  --border-subtle:    #000000;
  --shadow-card:      0 0 0 1px #000000;
  --shadow-card-hov:  0 0 0 2px #000000;
  --link:             #0033a0;
  --link-hover:       #001a6b;
  --accent:           #c4372f;
  --accent-strong:    #000000;

  --navbar-bg:           #000000;
  --navbar-bg-end:       #000000;
  --navbar-text:         #ffe600;
  --navbar-text-mute:    #ffe600;
  --navbar-active-bg:    #ffe600;
  --navbar-active-text:  #000000;
  --navbar-hover-bg:     rgba(255, 230, 0, 0.25);
  --navbar-border:       #ffe600;
}

/* ─── Tipografía ──────────────────────────────────────────────────────── */

@font-face {
  font-family: 'Inter';
  src: url('fonts/inter.woff2') format('woff2-variations');
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

* { box-sizing: border-box; }

html, body {
  background: var(--bg-app);
  color: var(--text-primary);
}

body, .container-fluid, .bslib-page-fillable {
  font-family: 'Inter', 'Source Sans 3', system-ui, -apple-system, sans-serif;
  color: var(--text-primary);
  background: var(--bg-app);
  letter-spacing: -0.005em;
  transition: background-color 0.25s ease, color 0.25s ease;
}

h1, h2, h3, h4, h5 {
  color: var(--text-heading);
  font-weight: 600;
  letter-spacing: -0.015em;
}

h2 { border-bottom: 2px solid var(--accent); padding-bottom: 0.4rem; }

p { color: var(--text-primary); }
.lead { color: var(--text-secondary) !important; }

a { color: var(--link); text-decoration: none; }
a:hover { color: var(--link-hover); text-decoration: underline; }

/* ─── Navbar (claro por defecto, configurable por paleta) ─────────────── */

.navbar {
  background: var(--navbar-bg) !important;
  background-image: linear-gradient(135deg, var(--navbar-bg), var(--navbar-bg-end)) !important;
  border-bottom: 3px solid var(--navbar-border);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.06);
  padding-top: 0.45rem;
  padding-bottom: 0.45rem;
}

.navbar .navbar-brand,
.navbar .navbar-brand:hover,
.navbar .navbar-brand-icman {
  color: var(--navbar-text) !important;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.navbar-brand-icman {
  display: flex; align-items: center; gap: 0.8rem;
}

.navbar-brand-icman img { height: 36px; }

/* Pestañas Inicio / Personas / Catálogo / etc. */
.navbar .nav-link,
.navbar .nav-item .nav-link,
.navbar-nav .nav-link {
  color: var(--navbar-text) !important;
  font-weight: 600;
  padding: 0.55rem 1.05rem !important;
  transition: background-color 0.15s ease;
  border-radius: 4px;
  letter-spacing: -0.005em;
}

.navbar .nav-link:hover,
.navbar .nav-link:focus {
  color: var(--navbar-active-text) !important;
  background: var(--navbar-hover-bg);
}

.navbar .nav-link.active,
.navbar .nav-item.show > .nav-link,
.navbar-nav .nav-link.active {
  color: var(--navbar-active-text) !important;
  background: var(--navbar-active-bg);
  font-weight: 700;
}

/* ─── Cards y value boxes ─────────────────────────────────────────────── */

.card, .bslib-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  box-shadow: var(--shadow-card);
  margin-bottom: 1rem;
  color: var(--text-primary);
}

.card-header {
  background: var(--bg-card-header);
  color: var(--text-heading);
  font-weight: 600;
  border-bottom: 1px solid var(--border-subtle);
}

html[data-palette="alto-contraste"] .card-header { color: #ffe600; }

.value-box, .bslib-value-box {
  background: var(--bg-surface);
  border-left: 4px solid var(--accent-strong);
  border-radius: 6px;
  padding: 1rem 1.25rem;
  transition: transform 0.1s ease, box-shadow 0.15s ease;
  color: var(--text-primary);
}

.value-box:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-card-hov);
}

.value-box .value-box-title {
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 0.75rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.value-box .value-box-value {
  color: var(--text-heading);
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.value-box .value-box-showcase {
  color: var(--accent);
  font-size: 1.5rem;
}

/* ─── Persona card ────────────────────────────────────────────────────── */

.persona-card {
  background: var(--bg-surface);
  border-radius: 12px;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  box-shadow: var(--shadow-card-hov);
  border: 1px solid var(--border-subtle);
}

.persona-avatar {
  width: 100px; height: 100px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--icman-deep), var(--icman-medium));
  color: white;
  display: flex; align-items: center; justify-content: center;
  font-size: 2.4rem; font-weight: 700;
  letter-spacing: -0.02em;
  box-shadow: 0 6px 20px rgba(0,0,0,0.30);
  margin-right: 1.5rem;
  flex-shrink: 0;
  text-shadow: 0 1px 2px rgba(0,0,0,0.25);
}

.persona-name {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text-heading);
  margin: 0 0 0.25rem 0;
  letter-spacing: -0.02em;
}

.persona-meta {
  color: var(--text-secondary);
  font-size: 0.95rem;
}

.alias-chip {
  display: inline-block;
  background: var(--bg-subtle);
  color: var(--text-heading);
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  padding: 3px 12px;
  margin: 3px 4px 3px 0;
  font-size: 0.85rem;
  font-weight: 500;
  transition: all 0.1s ease;
}

.alias-chip:hover {
  background: var(--icman-deep);
  color: #ffffff;
  border-color: var(--icman-deep);
  cursor: default;
}

.alias-chip .frec {
  color: var(--text-secondary);
  font-size: 0.75rem;
  margin-left: 4px;
}

/* ─── Sidebar ─────────────────────────────────────────────────────────── */

.bslib-sidebar-layout > .sidebar {
  background: var(--bg-subtle);
  border-right: 1px solid var(--border-subtle);
  color: var(--text-primary);
}

.sidebar h4, .sidebar .form-label, .sidebar label {
  color: var(--text-heading);
  font-weight: 600;
  font-size: 0.9rem;
  margin-top: 1rem;
  margin-bottom: 0.4rem;
}

/* ─── Inputs / Selectize ──────────────────────────────────────────────── */

.form-control, .form-select, .selectize-input, .selectize-control {
  border: 1px solid var(--border-subtle) !important;
  border-radius: 6px !important;
  font-size: 0.95rem;
  background: var(--bg-surface) !important;
  color: var(--text-primary) !important;
}

.selectize-input input { color: var(--text-primary) !important; }

.form-control:focus, .form-select:focus, .selectize-input.focus {
  border-color: var(--accent) !important;
  box-shadow: 0 0 0 3px rgba(95, 183, 194, 0.20) !important;
}

.selectize-dropdown {
  background: var(--bg-surface) !important;
  color: var(--text-primary) !important;
  border: 1px solid var(--border-subtle) !important;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.18);
}

.selectize-dropdown .option {
  color: var(--text-primary) !important;
  padding: 0.5rem 0.75rem;
  cursor: pointer;
}

.selectize-dropdown .option.active,
.selectize-dropdown .active.create,
.selectize-dropdown [data-selectable].active {
  background: var(--accent) !important;
  color: white !important;
}

/* Oculta la entrada vacía del dropdown del buscador de Personas */
#pers-persona_id + .selectize-control .selectize-dropdown [data-value=""],
.selectize-dropdown [data-value=""]:empty,
.selectize-dropdown [data-selectable][data-value=""] {
  display: none !important;
}

.selectize-dropdown .option .highlight {
  background: rgba(95, 183, 194, 0.30);
  color: inherit;
  border-radius: 2px;
  padding: 0 1px;
}

.selectize-input .item {
  background: var(--accent-strong) !important;
  color: white !important;
  border-radius: 4px;
  padding: 2px 8px;
}

/* Botones */
.btn-primary {
  background: var(--accent-strong) !important;
  border-color: var(--accent-strong) !important;
  color: white !important;
  font-weight: 500;
}
.btn-primary:hover {
  background: var(--icman-deep) !important;
  border-color: var(--icman-deep) !important;
}

.btn-outline-primary {
  color: var(--accent-strong) !important;
  border-color: var(--accent-strong) !important;
  background: transparent !important;
}
.btn-outline-primary:hover {
  background: var(--accent-strong) !important;
  color: white !important;
}

/* ─── Tabs internos (cards) ───────────────────────────────────────────── */

.nav-tabs, .nav-underline {
  border-bottom: 2px solid var(--border-subtle);
}

.nav-tabs .nav-link, .nav-underline .nav-link {
  color: var(--text-secondary);
  border: none;
  font-weight: 500;
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  background: transparent;
}

.nav-tabs .nav-link:hover, .nav-underline .nav-link:hover {
  color: var(--text-heading);
}

.nav-tabs .nav-link.active, .nav-underline .nav-link.active {
  color: var(--text-heading);
  background: transparent;
  border-bottom-color: var(--accent);
}

/* ─── Tablas ──────────────────────────────────────────────────────────── */

.dataTables_wrapper, table {
  font-size: 0.92rem;
  color: var(--text-primary);
}

th { background: var(--bg-subtle); color: var(--text-heading); }
td { color: var(--text-primary); }

table.gt_table {
  background: var(--bg-surface);
  color: var(--text-primary);
  border-collapse: collapse;
}

/* ─── Badge informativo ───────────────────────────────────────────────── */

.badge-info {
  display: inline-block;
  background: var(--icman-deep);
  color: #ffffff;
  border-radius: 6px;
  padding: 4px 10px;
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  white-space: nowrap;
  text-shadow: 0 1px 1px rgba(0, 0, 0, 0.20);
}

/* ─── Footer ──────────────────────────────────────────────────────────── */

.app-footer {
  margin-top: 3rem;
  padding: 1rem;
  text-align: center;
  color: var(--text-secondary);
  font-size: 0.85rem;
  border-top: 1px solid var(--border-subtle);
}

/* ─── Loading screen ──────────────────────────────────────────────────── */

#shiny-disconnected-overlay {
  background: rgba(10, 61, 74, 0.95) !important;
  color: white !important;
}

/* ─── Selector de paleta (flotante en esquina superior derecha) ──────── */

.palette-picker {
  position: fixed;
  top: 12px;
  right: 16px;
  z-index: 9999;
  display: flex;
  align-items: center;
  gap: 0.45rem;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  padding: 4px 6px 4px 10px;
  border-radius: 999px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.10);
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.82rem;
  color: var(--text-primary);
}

.palette-picker .pp-label {
  color: var(--text-secondary);
  font-weight: 500;
  white-space: nowrap;
}

.palette-picker select {
  border: none;
  background: transparent;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 0.85rem;
  font-weight: 600;
  padding: 2px 18px 2px 4px;
  border-radius: 999px;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--accent-strong) 50%),
                    linear-gradient(135deg, var(--accent-strong) 50%, transparent 50%);
  background-position: calc(100% - 12px) 50%, calc(100% - 7px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

.palette-picker select:focus {
  outline: 2px solid var(--accent);
