// ICMAN-CSIC · selector de paleta de fondo persistente.
// Inserta un <select> flotante en la esquina superior derecha y aplica
// data-palette en <html> para que el CSS active la paleta elegida.
(function () {
  "use strict";
  var KEY = "icman-palette";
  var DEFAULT = "claro";
  var OPTIONS = [
    { value: "claro",          label: "Claro" },
    { value: "crema",          label: "Crema" },
    { value: "marina",         label: "Marina" },
    { value: "oscuro",         label: "Oscuro" },
    { value: "alto-contraste", label: "Alto contraste" }
  ];

  function getStored() {
    try { return localStorage.getItem(KEY); } catch (e) { return null; }
  }
  function store(p) {
    try { localStorage.setItem(KEY, p); } catch (e) {}
  }

  function apply(p) {
    if (!p || p === "claro") {
      document.documentElement.removeAttribute("data-palette");
    } else {
      document.documentElement.setAttribute("data-palette", p);
    }
    var sel = document.getElementById("icman-palette-select");
    if (sel && sel.value !== p) sel.value = p;
  }

  function current() {
    var stored = getStored();
    if (stored && OPTIONS.some(function (o) { return o.value === stored; })) {
      return stored;
    }
    return DEFAULT;
  }

  // Aplicar inmediatamente, antes de que el DOM termine de pintar
  apply(current());

  function injectPicker() {
    if (document.getElementById("icman-palette-picker")) return;
    var wrap = document.createElement("div");
    wrap.id = "icman-palette-picker";
    wrap.className = "palette-picker";

    var lbl = document.createElement("span");
    lbl.className = "pp-label";
    lbl.textContent = "Tema";
    wrap.appendChild(lbl);

    var sel = document.createElement("select");
    sel.id = "icman-palette-select";
    sel.setAttribute("aria-label", "Cambiar paleta de color de la web");
    OPTIONS.forEach(function (o) {
      var op = document.createElement("option");
      op.value = o.value;
      op.textContent = o.label;
      sel.appendChild(op);
    });
    sel.value = current();
    sel.addEventListener("change", function (e) {
      var p = e.target.value;
      store(p);
      apply(p);
    });
    wrap.appendChild(sel);

    document.body.appendChild(wrap);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", injectPicker);
  } else {
    injectPicker();
  }

  // Re-inyectar si Shiny re-renderiza el body
  var observer = new MutationObserver(function () {
    if (!document.getElementById("icman-palette-picker") && document.body) {
      injectPicker();
    }
  });
  if (document.body) observer.observe(document.body, { childList: true });
})();

"""Filtros reutilizables (selectizes, sliders) usados en Catálogo y Visualizaciones."""

from __future__ import annotations

import shared
from components.i18n import TIPO_LABELS, t
from shiny import ui


def filter_tipos(input_id: str = "tipos"):
    """Selectize multi-select de tipos de actividad."""
    return ui.input_selectize(
        input_id,
        t("filtro_tipos"),
        choices={tipo: TIPO_LABELS.get(tipo, tipo) for tipo in shared.TIPOS_DISPONIBLES},
        multiple=True,
        options={"placeholder": "Cualquier tipo"},
    )


def filter_personas(input_id: str = "personas"):
    """Selectize multi-select de personas (predictivo, autocompletado)."""
    return ui.input_selectize(
        input_id,
        t("filtro_personas"),
        choices=shared.PERSONA_CHOICES,
        multiple=True,
        options={
            "placeholder": "Escribe un apellido…",
            "maxOptions": 1000,
            # Shiny configura labelField=label; no sobreescribir searchField.
            "openOnFocus": True,
            "selectOnTab": True,
            "hideSelected": True,
            "closeAfterSelect": True,
        },
    )


